import json, numpy as np, os
from rcb_client import Robot
from PIL import Image
S=json.load(open('/app/output/spec.json')); names=S['qpos']['layout']; ranges=np.array(S['qpos']['range']); jnames=S['proprio']['joints']
def rad_action(q): return np.clip(2*(np.array(q)-ranges[:,0])/(ranges[:,1]-ranges[:,0])-1,-1,1)
def measured(o):
 d=dict(zip(jnames,o['proprio']['joint_pos'])); q=[]
 for n in names:
  if '_A_' not in n: q.append(d[n]); continue
  j=n.replace('_A_','_')
  q.append(d[j[:-1]+'1']+d[j[:-1]+'2'] if j.endswith('J0') else d[j])
 return np.array(q)
def save(o,tag='current'):
 for k,v in o.get('images',{}).items(): Image.fromarray(v).save('/app/output/'+tag+'_'+k+'.png')
 json.dump({k:v for k,v in o.items() if k not in ('images','depth')},open('/app/output/'+tag+'.json','w'))
 print('step',o['step'],'done',o['done'],'reason',o['reason'],'resets',o['resets_left'],'imu',o.get('imu'));print('body',np.round(measured(o)[:21],3))
def move(q,n=50):
 r=Robot(); o=r.observe(False); a=measured(o) if not os.path.exists('/app/output/target.npy') else np.load('/app/output/target.npy')
 traj=np.array([rad_action(a+(q-a)*t) for t in np.linspace(1/n,1,n)])
 o=r.step('qpos',traj.tolist());np.save('/app/output/target.npy',q);save(o);return o
if __name__=='__main__':
 import sys
 r=Robot()
 if sys.argv[1]=='reset':
  o=r.reset(); np.save('/app/output/target.npy',measured(o));save(o)
 elif sys.argv[1]=='observe':save(r.observe())
 elif sys.argv[1]=='hold':
  q=np.load('/app/output/target.npy');save(r.step('qpos',[rad_action(q).tolist()]*int(sys.argv[2])))
 elif sys.argv[1]=='move':
  q=np.load('/app/output/target.npy') if os.path.exists('/app/output/target.npy') else measured(r.observe(False))
  for name,val in json.loads(sys.argv[3]).items():q[names.index(name)]=val
  move(q,int(sys.argv[2]))
