import numpy as np, json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from control import S,names,jnames
links=S['links']; ln=links['names']; par=dict(zip(ln,links['parent'])); axes=np.array(S['proprio']['axis']); pos=np.array(S['proprio']['position_m']); masses=np.array(links['mass_kg']); com=np.array(links['com_m'])
children=['left_hip_yaw_link','left_hip_roll_link','left_hip_pitch_link','left_knee_link','left_ankle_link','right_hip_yaw_link','right_hip_roll_link','right_hip_pitch_link','right_knee_link','right_ankle_link','torso_link','left_shoulder_pitch_link','left_shoulder_roll_link','left_shoulder_yaw_link','left_elbow_link','left_hand']+ln[17:41]+['right_shoulder_pitch_link','right_shoulder_roll_link','right_shoulder_yaw_link','right_elbow_link','right_hand']+ln[46:]
assert len(children)==69
ji=dict(zip(children,range(69)))
def fk(q):
 d=dict(zip(names,q)); jq=[]
 for n in jnames:
  an=n.replace('lh_','lh_A_').replace('rh_','rh_A_')
  if an in d:jq.append(d[an])
  elif an.endswith(('J1','J2')) and an[:-1]+'0' in d:jq.append(d[an[:-1]+'0']/2)
  else:raise ValueError(n)
 tf={'pelvis':np.eye(4)}
 for l in ln[1:]:
  j=ji[l]; rot=Rotation.from_rotvec(axes[j]*jq[j]).as_matrix(); T=np.eye(4);T[:3,:3]=rot;T[:3,3]=pos[j]-rot@pos[j];tf[l]=tf[par[l]]@T
 return tf

def point(tf,l,p):return tf[l][:3,:3]@p+tf[l][:3,3]
def report(q,pitch=0):
 tf=fk(q);R=Rotation.from_euler('y',pitch).as_matrix(); feet=[R@point(tf,l,np.array([.09,y,-1.065])) for l,y in [('left_ankle_link',.203),('right_ankle_link',-.203)]];root=np.array([.09,0,0])-np.mean(feet,axis=0)
 hands=[root+R@point(tf,l,np.array([.43,y,.087])) for l,y in [('lh_palm',.214),('rh_palm',-.214)]]
 cm=root+R@np.sum(np.array([point(tf,l,c) for l,c in zip(ln,com)])*masses[:,None],axis=0)/masses.sum()
 return root,hands,cm
if __name__=='__main__':
 q=np.zeros(61);q[[2,7]]=-.4;q[[3,8]]=.8;q[[4,9]]=-.4
 print(report(q))
